-- =====================================================================
-- Torte Living Business Operating System
-- Migration 0001 — Foundation: enums, business-code generation,
-- staff roles, audit trail and immutability controls.
--
-- Design rules (from the requirements specification):
--   * Every record has an internal UUID that is never entered by hand.
--   * Readable business codes (MT-000001, ORD-2026-000001 …) are
--     generated by the database, never by users or spreadsheets.
--   * Completed transactions cannot be silently deleted or rewritten.
--   * All writes that matter go through database functions that check
--     the caller's role; the browser never holds secret credentials.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Enumerations
-- ---------------------------------------------------------------------
create type staff_role as enum ('admin', 'manager', 'warehouse', 'packer', 'viewer');

create type location_type as enum (
  'warehouse', 'factory', 'contract_manufacturer', 'distributor', 'retailer', 'in_transit', 'other'
);

create type partner_role as enum (
  'distributor', 'sub_distributor', 'retailer', 'wholesaler', 'supplier',
  'manufacturer', 'logistics_provider', 'institutional'
);

create type stock_status as enum (
  'available',   -- sellable
  'packed',      -- allocated to an order and physically packed, awaiting dispatch
  'quarantine',  -- held pending quality decision
  'damaged',
  'expired',
  'returned',    -- returned stock awaiting inspection
  'in_transit'
);

create type stock_txn_type as enum (
  'goods_receipt', 'production_receipt', 'transfer', 'ownership_transfer',
  'status_change', 'pack', 'unpack', 'sale_issue', 'return_receipt', 'adjustment'
);

create type qa_status as enum ('pending', 'released', 'quarantined', 'rejected');

create type price_type as enum ('mrp', 'website', 'wholesale', 'distributor', 'retailer', 'institutional', 'promotional');

create type order_kind as enum ('consumer', 'b2b');

create type order_status as enum (
  'pending_payment', 'confirmed', 'packing', 'packed', 'dispatched', 'delivered',
  'delivery_failed', 'cancelled'
);

create type payment_status as enum ('unpaid', 'paid', 'partially_refunded', 'refunded', 'cod_pending');

create type payment_kind as enum ('payment', 'refund');

create type shipment_status as enum ('dispatched', 'delivered', 'failed', 'cancelled');

create type scan_result as enum (
  'accepted', 'unknown_code', 'wrong_product', 'excess_quantity', 'batch_required',
  'batch_expired', 'batch_not_released', 'insufficient_batch_stock', 'order_not_packable'
);

create type integration_status as enum ('received', 'processed', 'duplicate', 'failed');

-- ---------------------------------------------------------------------
-- Business-code generation
--   next_code('MT')            -> MT-000001
--   next_code('ORD', true)     -> ORD-2026-000001  (yearly sequence)
-- Codes are allocated under a row lock, so they are unique and gap-free
-- per prefix even under concurrent use.
-- ---------------------------------------------------------------------
create table code_sequences (
  prefix     text not null,
  year       int  not null default 0,     -- 0 = non-yearly sequence
  last_value bigint not null default 0,
  primary key (prefix, year)
);

create or replace function next_code(p_prefix text, p_yearly boolean default false)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_year int := case when p_yearly then extract(year from (now() at time zone 'Asia/Kolkata'))::int else 0 end;
  v_val  bigint;
begin
  insert into code_sequences as s (prefix, year, last_value)
  values (p_prefix, v_year, 1)
  on conflict (prefix, year) do update set last_value = s.last_value + 1
  returning last_value into v_val;

  if p_yearly then
    return p_prefix || '-' || v_year || '-' || lpad(v_val::text, 6, '0');
  end if;
  return p_prefix || '-' || lpad(v_val::text, 6, '0');
end;
$$;

-- Generic trigger: fills NEW.code from TG_ARGV[0] (prefix) and TG_ARGV[1] ('yearly').
create or replace function trg_assign_code()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.code is null or new.code = '' then
    new.code := next_code(tg_argv[0], coalesce(tg_argv[1], '') = 'yearly');
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------
-- Staff and roles
-- Users sign in with Supabase Auth; their role lives here.
-- ---------------------------------------------------------------------
create table staff_profiles (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  full_name  text not null,
  role       staff_role not null default 'viewer',
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

create or replace function current_staff_role()
returns staff_role
language sql
stable
security definer
set search_path = public
as $$
  select role from staff_profiles where user_id = auth.uid() and active
$$;

-- Raises unless the caller is an active staff member holding one of the roles.
-- 'admin' always passes.
create or replace function require_role(variadic p_roles staff_role[])
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_role staff_role := current_staff_role();
begin
  if auth.uid() is null or v_role is null then
    raise exception 'Not signed in as an active staff member' using errcode = '42501';
  end if;
  if v_role <> 'admin' and not (v_role = any (p_roles)) then
    raise exception 'Your role (%) is not allowed to do this', v_role using errcode = '42501';
  end if;
  return auth.uid();
end;
$$;

create or replace function require_staff()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select require_role('admin', 'manager', 'warehouse', 'packer', 'viewer')
$$;

-- First signed-in user may claim the admin role when no admin exists yet.
-- Lets a non-developer bootstrap the system without touching SQL.
create or replace function claim_first_admin(p_full_name text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('claim_first_admin'));
  if exists (select 1 from staff_profiles where role = 'admin' and active) then
    raise exception 'An administrator already exists. Ask them to add you.' using errcode = '42501';
  end if;
  insert into staff_profiles (user_id, full_name, role)
  values (auth.uid(), p_full_name, 'admin')
  on conflict (user_id) do update set role = 'admin', active = true, full_name = excluded.full_name;
  return jsonb_build_object('role', 'admin');
end;
$$;

create or replace function get_my_profile()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select jsonb_build_object('user_id', user_id, 'full_name', full_name, 'role', role, 'active', active)
       from staff_profiles where user_id = auth.uid()),
    jsonb_build_object('user_id', auth.uid(), 'role', null,
      'admin_exists', exists (select 1 from staff_profiles where role = 'admin' and active))
  )
$$;

-- ---------------------------------------------------------------------
-- Audit trail
-- ---------------------------------------------------------------------
create table audit_log (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  record_id   uuid,
  action      text not null,
  old_data    jsonb,
  new_data    jsonb,
  actor       uuid,
  occurred_at timestamptz not null default now()
);

create or replace function trg_audit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into audit_log (table_name, record_id, action, old_data, new_data, actor)
  values (
    tg_table_name,
    case when tg_op = 'DELETE' then (to_jsonb(old) ->> 'id')::uuid else (to_jsonb(new) ->> 'id')::uuid end,
    tg_op,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end,
    auth.uid()
  );
  return coalesce(new, old);
end;
$$;

-- Blocks UPDATE/DELETE on append-only ledgers (stock movements, scans, payments …).
create or replace function trg_immutable()
returns trigger
language plpgsql
as $$
begin
  raise exception '% records are permanent and cannot be % — post a correcting entry instead',
    tg_table_name, lower(tg_op) || 'd' using errcode = '42501';
end;
$$;

-- Blocks DELETE only (records may progress through statuses but never vanish).
create or replace function trg_no_delete()
returns trigger
language plpgsql
as $$
begin
  raise exception '% records cannot be deleted — cancel or deactivate instead', tg_table_name
    using errcode = '42501';
end;
$$;

create or replace function today_ist()
returns date
language sql
stable
as $$ select (now() at time zone 'Asia/Kolkata')::date $$;
